    receive() external payable {}
    function run(uint64 n, uint64 t, uint256 f) public {
        uint64 numberBefore = c.number(); if (__ESBMC_reverted()) return;
        uint64 timestampBefore = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 overheadBefore = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        bool reverted1;
        bool reverted2;
        c.setL1BlockValues(n, t, f, bytes32(uint256(n)), n, bytes32(uint256(t)), f, n); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }
        c.setL1BlockValues(t, n, n, bytes32(uint256(f)), t, bytes32(uint256(n)), f, t); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
