pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 t, uint256 f) internal {
        uint64 numberBefore;
        try c.number() returns (uint64 __r) { numberBefore = __r; } catch { return; }
        uint64 timestampBefore;
        try c.timestamp() returns (uint64 __r) { timestampBefore = __r; } catch { return; }
        uint256 overheadBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { overheadBefore = __r; } catch { return; }
        bool reverted1;
        bool reverted2;
        try c.setL1BlockValues(n, t, f, bytes32(uint256(n)), n, bytes32(uint256(t)), f, n) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        try c.setL1BlockValues(t, n, n, bytes32(uint256(f)), t, bytes32(uint256(n)), f, t) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assertTrue(reverted1 && reverted2 && c.number() == numberBefore && c.timestamp() == timestampBefore && c.l1FeeOverhead() == overheadBefore);
    }

    function testFuzz_run(uint64 n, uint64 t, uint256 f) public {
        _run(n, t, f);
    }

    receive() external payable {}
}
